import{_ as s,o as e,c as n,a2 as l}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"定时器 (Timers)","description":"","frontmatter":{},"headers":[],"relativePath":"timers.md","filePath":"timers.md","lastUpdated":1669882888000}'),t={name:"timers.md"};function i(p,a,c,d,o,r){return e(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="定时器-timers" tabindex="-1">定时器 (Timers)</h1><hr><p style="font:italic 1em sans-serif;color:#78909C;">此章节待补充或完善...</p><p style="font:italic 1em sans-serif;color:#78909C;">Marked by SuperMonster003 on Oct 22, 2022.</p><hr><p>timers 模块暴露了一个全局的 API, 用于在某个未来时间段调用调度函数. 因为定时器函数是全局的, 所以使用该 API 无需调用 timers.***</p><p>Auto.js 中的计时器函数实现了与 Web 浏览器提供的定时器类似的 API, 除了它使用了一个不同的内部实现, 它是基于 Android Looper-Handler消息循环机制构建的. 其实现机制与Node.js比较相似.</p><p>例如, 要在5秒后发出消息&quot;hello&quot;:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setTimeout(function(){</span></span>
<span class="line"><span>    toast(&quot;hello&quot;)</span></span>
<span class="line"><span>}, 5000);</span></span></code></pre></div><p>需要注意的是, 这些定时器仍然是单线程的. 如果脚本主体有耗时操作或死循环, 则设定的定时器不能被及时执行, 例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setTimeout(function(){</span></span>
<span class="line"><span>    //这里的语句会在15秒后执行而不是5秒后</span></span>
<span class="line"><span>    toast(&quot;hello&quot;)</span></span>
<span class="line"><span>}, 5000);</span></span>
<span class="line"><span>//暂停10秒</span></span>
<span class="line"><span>sleep(10000);</span></span></code></pre></div><p>再如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setTimeout(function(){</span></span>
<span class="line"><span>    //这里的语句永远不会被执行</span></span>
<span class="line"><span>    toast(&quot;hello&quot;)</span></span>
<span class="line"><span>}, 5000);</span></span>
<span class="line"><span>//死循环</span></span>
<span class="line"><span>while(true);</span></span></code></pre></div><h2 id="setinterval-callback-delay-args" tabindex="-1">setInterval(callback, delay[, ...args])</h2><ul><li><code>callback</code> {Function} 当定时器到点时要调用的函数.</li><li><code>delay</code> {number} 调用 callback 之前要等待的毫秒数.</li><li><code>...args</code> {any} 当调用 callback 时要传入的可选参数.</li></ul><p>预定每隔 delay 毫秒重复执行的 callback. 返回一个用于 clearInterval() 的 id.</p><p>当 delay 小于 0 时, delay 会被设为 0.</p><h2 id="settimeout-callback-delay-args" tabindex="-1">setTimeout(callback, delay[, ...args])</h2><ul><li><code>callback</code> {Function} 当定时器到点时要调用的函数.</li><li><code>delay</code> {number} 调用 callback 之前要等待的毫秒数.</li><li><code>...args</code> {any} 当调用 callback 时要传入的可选参数.</li></ul><p>预定在 delay 毫秒之后执行的单次 callback. 返回一个用于 clearTimeout() 的 id.</p><p>callback 可能不会精确地在 delay 毫秒被调用. Auto.js 不能保证回调被触发的确切时间, 也不能保证它们的顺序. 回调会在尽可能接近所指定的时间上调用.</p><p>当 delay 小于 0 时, delay 会被设为 0.</p><h2 id="setimmediate-callback-args" tabindex="-1">setImmediate(callback[, ...args])</h2><ul><li><code>callback</code> {Function} 在Looper循环的当前回合结束时要调用的函数.</li><li><code>...args</code> {any} 当调用 callback 时要传入的可选参数.</li></ul><p>预定立即执行的 callback, 它是在 I/O 事件的回调之后被触发. 返回一个用于 clearImmediate() 的 id.</p><p>当多次调用 setImmediate() 时, callback 函数会按照它们被创建的顺序依次执行. 每次事件循环迭代都会处理整个回调队列. 如果一个立即定时器是被一个正在执行的回调排入队列的, 则该定时器直到下一次事件循环迭代才会被触发.</p><p>setImmediate()、setInterval() 和 setTimeout() 方法每次都会返回表示预定的计时器的id. 它们可用于取消定时器并防止触发.</p><h2 id="clearinterval-id" tabindex="-1">clearInterval(id)</h2><ul><li><code>id</code> {number} 一个 setInterval() 返回的 id.</li></ul><p>取消一个由 setInterval() 创建的循环定时任务.</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//每5秒就发出一次hello</span></span>
<span class="line"><span>var id = setInterval(function(){</span></span>
<span class="line"><span>    toast(&quot;hello&quot;);</span></span>
<span class="line"><span>}, 5000);</span></span>
<span class="line"><span>//1分钟后取消循环</span></span>
<span class="line"><span>setTimeout(function(){</span></span>
<span class="line"><span>    clearInterval(id);</span></span>
<span class="line"><span>}, 60 * 1000);</span></span></code></pre></div><h2 id="cleartimeout-id" tabindex="-1">clearTimeout(id)</h2><ul><li><code>id</code> {number} 一个 setTimeout() 返回的 id.</li></ul><p>取消一个由 setTimeout() 创建的定时任务.</p><h2 id="clearimmediate-id" tabindex="-1">clearImmediate(id)</h2><ul><li><code>id</code> {number} 一个 setImmediate() 返回的 id.</li></ul><p>取消一个由 setImmediate() 创建的 Immediate 对象.</p>`,38)])])}const b=s(t,[["render",i]]);export{m as __pageData,b as default};
